    const p2 = lock.acquire();
    assert.equal(lock.queueLength, 2); // active + waiting

    release1();
    const release2 = await p2;
    assert.equal(lock.queueLength, 1);
    release2();
    assert.equal(lock.queueLength, 0);
  });
});

