    browser = new Browser();
    await browser.start();

    const started = Date.now();
    await assert.rejects(
      browser.send('Runtime.evaluate', {
        expression: 'new Promise(() => {})', // never resolves
        awaitPromise: true
      }, 1000),
      /Timeout: Runtime.evaluate/
    );
    assert.ok(Date.now() - started < 10000, 'timeout should be enforced');
  });
});

