arguments.command:
cd /root/browser-mcp && timeout 30 node --input-type=module -e "
import { spawn } from 'node:child_process';
import { CDPClient } from './src/cdp.js';

const serverCode = \`
const { WebSocketServer } = require('ws');
const wss = new WebSocketServer({ port: 18924 });
wss.on('connection', (ws) => {
  ws._socket.pause(); // stop reading -> unread data accumulates -> RST on kill
});
setInterval(() => {}, 1000);
\`;
const child = spawn(process.execPath, ['-e', serverCode], { stdio: 'ignore' });
await new Promise(r => setTimeout(r, 700));

const c = new CDPClient();
await c.connect('ws://127.0.0.1:18924');
console.log('connected; flooding sends to fill the server receive buffer...');
const big = 'x'.repeat(1024 * 1024);
const sends = [];
for (let i = 0; i < 8; i++) sends.push(c.send('Runtime.evaluate', { expression: '1', payload: big }, 30000).catch(e => e));
await new Promise(r => setTimeout(r, 500));
child.kill('SIGKILL');
await new Promise(r => setTimeout(r, 2000));
console.log('parent still alive after kill + 2s');
const results = await Promise.all(sends);
for (const r of results) console.log('send outcome:', r instanceof Error ? r.message.slice(0, 50) : 'resolved');
process.exit(0);
" 2>&1 | head -40; echo "EXIT=$?"

